local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local HttpService = game:GetService("HttpService")
local LocalPlayer = Players.LocalPlayer
local Mouse = LocalPlayer:GetMouse()

local GROUP_ID = 44482188
local TEAM_NAME = "Администрация"
local PER_PAGE = 10
local REQUEST_INTERVAL = 0.3
local RETRY_DELAY = 15
local REFRESH_INTERVAL = 0.5

local MOD_MIN_RANK = 16

local IGNORED_RANKS = {
    [1]  = true,
    [2]  = true,
    [9]  = true,
    [10] = true,
    [11] = true,
    [15] = true,
}

local RANK_NAMES = {
    [255] = "Owner", [254] = "FAME", [253] = "Co-Owner",
    [60] = "Trusted Developer", [50] = "Developer",
    [21] = "Manager", [19] = "Head Admin", [18] = "Administrator",
    [17] = "Moderator", [16] = "Helper / Role Giver",
    [15] = "FSB", [11] = "Rosgvardiya", [10] = "Prosecutor / MVD",
    [9] = "OPG", [3] = "Tester", [2] = "Content Maker",
    [1] = "Citizen", [0] = "Guest",
}

local ROLE_TRANSLATIONS = {
    ["Владелеццц"]              = "Owner",
    ["FAME"]                    = "FAME",
    ["Совладелец"]              = "Co-Owner",
    ["Доверенные разработчики"] = "Trusted Developer",
    ["Разработчики"]            = "Developer",
    ["Менеджеры"]               = "Manager",
    ["Гл. Администраторы"]      = "Head Admin",
    ["Администраторы"]          = "Administrator",
    ["Модераторы"]              = "Moderator",
    ["Хелпер"]                  = "Helper",
    ["Выдача ролей"]            = "Role Giver",
    ["ФСБ"]                     = "FSB",
    ["Росгвардия"]              = "Rosgvardiya",
    ["Прокуратура"]             = "Prosecutor",
    ["МВД"]                     = "MVD",
    ["ОПГ"]                     = "OPG",
    ["Тестеры"]                 = "Tester",
    ["Контент-мейкеры"]         = "Content Maker",
    ["Граждане"]                = "Citizen",
    ["Гость"]                   = "Guest",
}

local LINE_HEIGHT   = 18
local COLOR_NORMAL  = Color3.fromRGB(255, 255, 255)
local COLOR_MOD     = Color3.fromRGB(255, 60, 60)
local COLOR_DIM     = Color3.fromRGB(180, 180, 180)

local headerText = Drawing.new("Text")
headerText.Size     = 16
headerText.Color    = COLOR_NORMAL
headerText.Outline  = true
headerText.Visible  = true
headerText.Text     = "STAFF LIST"

local LINE_POOL_SIZE = 20
local lineObjects = {}
for i = 1, LINE_POOL_SIZE do
    local t = Drawing.new("Text")
    t.Size    = 16
    t.Color   = COLOR_NORMAL
    t.Outline = true
    t.Visible = false
    lineObjects[i] = t
end

local modAlert = Drawing.new("Text")
modAlert.Size    = 28
modAlert.Color   = COLOR_MOD
modAlert.Outline = true
modAlert.Center  = true
modAlert.Visible = false
modAlert.Text    = "!!-MODERATOR ON SERVER-!!"

local textX, textY = 20, 100
headerText.Position = Vector2.new(textX, textY)

local function updateAlertPosition()
    local cam = workspace.CurrentCamera
    if cam then
        local vp = cam.ViewportSize
        modAlert.Position = Vector2.new(vp.X * 0.5, vp.Y * 0.16)
    end
end
updateAlertPosition()

local dragging = false
local dragOffsetX, dragOffsetY = 0, 0
local textWidth, textHeight = 200, 40

local currentPage = 0
local totalPages = 1

local cachedRanks = {}
local failedCache = {}
local requestQueue = {}
local pendingRequests = {}
local queuedSet = {}
local processingQueue = false

function startQueueProcessor()
    if processingQueue then return end
    processingQueue = true

    task.spawn(function()
        while #requestQueue > 0 do
            local plr = table.remove(requestQueue, 1)
            if plr then
                queuedSet[plr.UserId] = nil
                pendingRequests[plr.UserId] = true

                local url = "https://groups.roblox.com/v2/users/" .. plr.UserId .. "/groups/roles"
                local success, response = pcall(function() return httpget(url) end)
                pendingRequests[plr.UserId] = nil

                if success and response and response ~= "" then
                    local ok, data = pcall(function() return HttpService:JSONDecode(response) end)
                    if ok and data and data.data then
                        local found = false
                        for _, g in ipairs(data.data) do
                            if g.group.id == GROUP_ID then
                                cachedRanks[plr.UserId] = {
                                    rank = g.role.rank,
                                    name = g.role.name
                                }
                                found = true
                                break
                            end
                        end
                        if not found then cachedRanks[plr.UserId] = false end
                    else
                        failedCache[plr.UserId] = tick()
                    end
                else
                    failedCache[plr.UserId] = tick()
                end

                task.wait(REQUEST_INTERVAL)
            end
        end
        processingQueue = false
    end)
end

local function enqueuePlayer(plr)
    if cachedRanks[plr.UserId] ~= nil then return end
    if pendingRequests[plr.UserId] then return end
    if queuedSet[plr.UserId] then return end
    local lastFail = failedCache[plr.UserId]
    if lastFail and (tick() - lastFail) < RETRY_DELAY then return end

    queuedSet[plr.UserId] = true
    table.insert(requestQueue, plr)
    startQueueProcessor()
end

local function translateRole(roleName, rank)
    if roleName and type(roleName) == "string" then
        if ROLE_TRANSLATIONS[roleName] then
            return ROLE_TRANSLATIONS[roleName]
        end
        for ru, en in pairs(ROLE_TRANSLATIONS) do
            if string.find(string.lower(roleName), string.lower(ru), 1, true) then
                return en
            end
        end
    end
    if rank and RANK_NAMES[rank] then
        return RANK_NAMES[rank]
    end
    return "Rank " .. tostring(rank or "?")
end

local VK_LEFT  = 0x25
local VK_RIGHT = 0x27
local prevLeft, prevRight = false, false

RunService.RenderStepped:Connect(function()
    updateAlertPosition()

    local leftDown  = iskeypressed(VK_LEFT)
    local rightDown = iskeypressed(VK_RIGHT)

    if leftDown and not prevLeft then
        currentPage = currentPage - 1
        if currentPage < 0 then
            currentPage = math.max(0, totalPages - 1)
        end
    end
    if rightDown and not prevRight then
        currentPage = currentPage + 1
        if currentPage >= totalPages then
            currentPage = 0
        end
    end
    prevLeft, prevRight = leftDown, rightDown

    local mouseX, mouseY = Mouse.X, Mouse.Y
    local mouseDown = ismouse1pressed()

    if mouseDown and not dragging then
        if mouseX >= textX and mouseX <= textX + textWidth and
           mouseY >= textY and mouseY <= textY + textHeight then
            dragging = true
            dragOffsetX = mouseX - textX
            dragOffsetY = mouseY - textY
        end
    end

    if dragging and mouseDown then
        textX = mouseX - dragOffsetX
        textY = mouseY - dragOffsetY
        headerText.Position = Vector2.new(textX, textY)
        for i = 1, LINE_POOL_SIZE do
            if lineObjects[i].Visible then
                lineObjects[i].Position = Vector2.new(textX, textY + i * LINE_HEIGHT)
            end
        end
    end

    if not mouseDown then dragging = false end
end)

task.spawn(function()
    while true do
        local currentPlayers = Players:GetPlayers()
        local currentIds = {}
        for _, plr in ipairs(currentPlayers) do
            currentIds[plr.UserId] = true
            enqueuePlayer(plr)
        end

        for uid in pairs(cachedRanks) do
            if not currentIds[uid] then cachedRanks[uid] = nil end
        end
        for uid in pairs(failedCache) do
            if not currentIds[uid] then failedCache[uid] = nil end
        end
        for uid in pairs(queuedSet) do
            if not currentIds[uid] then queuedSet[uid] = nil end
        end

        local staffList = {}
        for _, plr in ipairs(currentPlayers) do
            local isStaff = false
            local roleText = ""
            local isMod = false

            if plr.Team and plr.Team.Name == TEAM_NAME then
                isStaff = true
                roleText = "Administration"
                isMod = true
            end

            if not isStaff then
                local data = cachedRanks[plr.UserId]
                if data and data ~= false and data.rank and data.rank > 0 then
                    isStaff = true
                    roleText = translateRole(data.name, data.rank)
                    if data.rank >= MOD_MIN_RANK and not IGNORED_RANKS[data.rank] then
                        isMod = true
                    end
                end
            end

            if isStaff then
                table.insert(staffList, {
                    text  = plr.Name .. " - " .. roleText,
                    isMod = isMod,
                })
            end
        end

        local totalPlayers = #staffList
        totalPages = math.max(1, math.ceil(totalPlayers / PER_PAGE))

        if currentPage >= totalPages then currentPage = totalPages - 1 end
        if currentPage < 0 then currentPage = 0 end

        local pendingCount = #requestQueue
        for _ in pairs(pendingRequests) do pendingCount = pendingCount + 1 end

        local lines = {}
        lines[1] = { text = "=== STAFF LIST (" .. totalPlayers .. ") ===", color = COLOR_NORMAL }

        if totalPlayers == 0 then
            lines[#lines + 1] = { text = "No staff found.", color = COLOR_DIM }
        else
            local startIdx = currentPage * PER_PAGE + 1
            local endIdx = math.min(startIdx + PER_PAGE - 1, totalPlayers)
            for i = startIdx, endIdx do
                local entry = staffList[i]
                lines[#lines + 1] = {
                    text  = i .. ". " .. entry.text,
                    color = entry.isMod and COLOR_MOD or COLOR_NORMAL,
                }
            end
            if totalPages > 1 then
                lines[#lines + 1] = {
                    text  = "-- Page " .. (currentPage + 1) .. "/" .. totalPages .. " [<-/->] --",
                    color = COLOR_DIM,
                }
            end
        end
        if pendingCount > 0 then
            lines[#lines + 1] = {
                text  = "Scanning... (" .. pendingCount .. " left)",
                color = COLOR_DIM,
            }
        end

        headerText.Text     = lines[1].text
        headerText.Color    = lines[1].color
        headerText.Position = Vector2.new(textX, textY)
        headerText.Visible  = true

        for i = 2, #lines do
            local obj = lineObjects[i - 1]
            if obj then
                obj.Text     = lines[i].text
                obj.Color    = lines[i].color
                obj.Position = Vector2.new(textX, textY + (i - 1) * LINE_HEIGHT)
                obj.Visible  = true
            end
        end
        for i = #lines, LINE_POOL_SIZE do
            if lineObjects[i] then lineObjects[i].Visible = false end
        end

        local maxW = 0
        for _, l in ipairs(lines) do
            local w = #l.text * (headerText.Size * 0.6)
            if w > maxW then maxW = w end
        end
        textWidth  = maxW
        textHeight = #lines * LINE_HEIGHT

        local hasMod = false
        for _, entry in ipairs(staffList) do
            if entry.isMod then
                hasMod = true
                break
            end
        end
        modAlert.Visible = hasMod

        task.wait(REFRESH_INTERVAL)
    end
